 dict(slug="follow-up", name="Follow-up",
  title="Real Estate Follow-Up Messages for WhatsApp (Buyers & Tenants)",
  meta="WhatsApp follow-up templates for real estate leads: after enquiries, inspections, offers and closings, plus messages that revive cold leads politely.",
  lede="Most deals come from the second, third or fourth message, not the first. These follow-ups stay helpful instead of pushy.",
  intro=["Every follow-up should give the lead something: a new option, an answer, a document, or a deadline. \"Just checking in\" on its own rarely gets a reply.",
         "Space them out (day 1, day 3, day 7, then monthly) and stop when someone asks you to."],
  tpls=[("Day 1 after enquiry", "Fast, helpful", "Hi [First name], thanks for asking about the [Area] [3]-bed 🙏 I've attached the full video. Would you like to see it this week, or should I send similar options too?"),
        ("Day 3 with value", "Adds a new option", "Hi [First name], I found two more homes in [Area] around ₦___ that fit what you described. Want me to send them?"),
        ("Day 7 soft close", "Keeps the door open", "Hi [First name], no pressure at all. Are you still searching, or should I pause the alerts for now? Either way is fine 😊"),
        ("After inspection", "Within 24 hours", "Thanks for viewing the [Area] property yesterday. On a scale of 1–10 how close was it? Tell me what would make it a 10 and I'll find it."),
        ("After an offer", "Status update", "Update on your offer for [property] 📝 The seller has [received it / countered at ₦___]. Let's talk at [time] today?"),
        ("Documents chase", "Gentle reminder", "Hi [First name], just a reminder that we need [your ID and proof of payment] to finalise. Send whenever you're ready and I'll handle the rest."),
        ("After closing", "Referral ask", "Congratulations again on your new home 🏡🎉 If you know anyone else looking to buy, sell or rent, I'd be grateful for the introduction."),
        ("Cold lead revival", "3+ months later", "Hi [First name], it's [Your name] from [Agency]. You were looking in [Area] earlier this year. Prices and new listings have moved since then. Want a quick update?"),
        ("Tenant renewal", "Before rent expires", "Hi [First name], your rent at [property] is due for renewal on [date]. Shall we start the renewal so there's no last-minute rush?"),
        ("Seller update", "Weekly to your sellers", "Weekly update for [property] 📊\nViewings: [5]\nEnquiries: [12]\nFeedback: [price seen as high for the finish]\nSuggested next step: [new photos / price review]")],
  tips=["Reply to new enquiries within minutes; speed is the biggest single factor in converting WhatsApp leads.",
        "Every follow-up should add value: a video, a new option, an answer or a document.",
        "Use the 1-3-7 rhythm, then monthly. Stop if someone asks you to.",
        "Label chats (WhatsApp Business labels) as New, Viewing, Offer, Closed to see who needs a nudge.",
        "Send weekly updates to sellers even when there's no news; silence makes sellers switch agents."],
  faq=[COMMON_FAQ,
       ("How many times should I follow up a property lead?", "Three times in the first week (day 1, 3 and 7) and then about once a month, as long as each message adds something useful."),
       ("How do I follow up without being annoying?", "Give a reason with every message, such as a new listing, an answer or a document, and offer an easy way to pause."),
       ("Should I use WhatsApp Business?", "Yes, if you can. Labels, quick replies and a business profile make follow-ups faster and look more professional.")],
  related=["/whatsapp/inspection-invite/", "/captions/sold/", "/whatsapp/price-drop/"]),

