def pages():
    out = []
    for e in EVENTS:
        out.append(dict(path=f"/whatsapp/{e['slug']}/", section="whatsapp", crumb=f"{e['name']} WhatsApp templates",
                        title=e["title"] if len(e["title"]) > 60 else e["title"] + " | ListingKit", meta=e["meta"],
                        h1=f"WhatsApp {e['name'].lower()} messages for real estate", eyebrow="WhatsApp templates",
                        lede=e["lede"], intro=e["intro"], groups=[("", e["tpls"])],
                        groups_title="Copy-ready WhatsApp messages", tips=e["tips"],
                        tips_title="How to send them so people reply", faq=e["faq"],
                        related=e["related"] + [f"/whatsapp/{x['slug']}/" for x in EVENTS if x["slug"] != e["slug"] and f"/whatsapp/{x['slug']}/" not in e["related"]][:3] + ["/whatsapp/"],
                        blurb=e["lede"][:120]))
    return out
